export const DATA_TAB = "Data";
export const FEED_TAB = "Feed";
export const DAILY_TAB = "Daily Ad Spend";
export const TRACKER_TAB = "Tracker names";

export type WriteTab = typeof DATA_TAB | typeof FEED_TAB | typeof DAILY_TAB;

export type WriteTarget = {
  tab: WriteTab;
  reason: string;
  dataHasFormula: boolean;
};

function isFormulaCell(value: unknown): boolean {
  if (typeof value !== "string") return false;
  const t = value.trim();
  return t.startsWith("=") || t.startsWith("+") || t.startsWith("@");
}

/** True if a tab (or part of it) is generated by a formula. */
export function dataRangeHasFormula(values: unknown[][] | undefined): boolean {
  if (!values || values.length === 0) return false;
  for (const row of values) {
    for (const cell of row ?? []) {
      if (isFormulaCell(cell)) return true;
    }
  }
  return false;
}

export function resolveWriteTarget(opts: {
  dataFormulaValues?: unknown[][];
  tabNames?: string[];
  dailyFormulaValues?: unknown[][];
}): WriteTarget {
  const tabNames = opts.tabNames ?? [];
  const dailyExists = tabNames.includes(DAILY_TAB);
  const dailyHasFormula = dataRangeHasFormula(opts.dailyFormulaValues);
  if (dailyExists && !dailyHasFormula) {
    return {
      tab: DAILY_TAB,
      dataHasFormula: dataRangeHasFormula(opts.dataFormulaValues),
      reason:
        "Daily Ad Spend exists and is plain values, so rows are appended/updated there. Data is left untouched."
    };
  }

  const dataHasFormula = dataRangeHasFormula(opts.dataFormulaValues);
  if (dataHasFormula) {
    return {
      tab: FEED_TAB,
      dataHasFormula: true,
      reason:
        "Data!A:D contains a formula, so rows are written to Feed (same 4 columns) and Data is left untouched."
    };
  }
  return {
    tab: DATA_TAB,
    dataHasFormula: false,
    reason: "Data!A:D is plain values, so rows are appended/updated on Data."
  };
}

export function looksLikeHeaderRow(row: unknown[] | undefined): boolean {
  const a = String(row?.[0] ?? "")
    .trim()
    .toLowerCase();
  const b = String(row?.[1] ?? "")
    .trim()
    .toLowerCase();
  return a === "date" && b === "client";
}
